CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE permissions (name VARCHAR(100) PRIMARY KEY);
CREATE TABLE role_permissions (role_id BIGINT NOT NULL, permission VARCHAR(100) NOT NULL, PRIMARY KEY(role_id,permission), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission) REFERENCES permissions(name));
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role_id BIGINT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE auth_sessions (id VARCHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at BIGINT NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE refresh_tokens (jti VARCHAR(36) PRIMARY KEY, session_id VARCHAR(36) NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(session_id) REFERENCES auth_sessions(id) ON DELETE CASCADE);
CREATE TABLE login_attempts (username VARCHAR(100) PRIMARY KEY, failures INT NOT NULL DEFAULT 0, locked_until BIGINT NOT NULL DEFAULT 0);
CREATE TABLE idempotency_requests (user_id BIGINT NOT NULL, request_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, fingerprint CHAR(64) NOT NULL, status_code INT NULL, response MEDIUMBLOB NULL, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,request_key), FOREIGN KEY(user_id) REFERENCES users(id));
ALTER TABLE document_lines ADD delivered_quantity BIGINT NOT NULL DEFAULT 0, ADD on_delivery_quantity BIGINT NOT NULL DEFAULT 0;
CREATE TABLE delivery_orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, sales_invoice_id BIGINT NOT NULL, driver_name VARCHAR(200) NOT NULL, date DATE NOT NULL, address VARCHAR(1000) NOT NULL, note TEXT NOT NULL, cancellation_note TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Draft', created_by BIGINT NOT NULL, approved_by BIGINT NULL, FOREIGN KEY(sales_invoice_id) REFERENCES documents(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(approved_by) REFERENCES users(id));
CREATE TABLE delivery_order_details (id BIGINT PRIMARY KEY AUTO_INCREMENT, delivery_order_id BIGINT NOT NULL, sales_invoice_detail_id BIGINT NOT NULL, product_name VARCHAR(200) NOT NULL, quantity BIGINT NOT NULL, notes TEXT NOT NULL, UNIQUE(delivery_order_id,sales_invoice_detail_id), FOREIGN KEY(delivery_order_id) REFERENCES delivery_orders(id), FOREIGN KEY(sales_invoice_detail_id) REFERENCES document_lines(id));
CREATE TABLE invoice_void_requests (id BIGINT PRIMARY KEY AUTO_INCREMENT, invoice_id BIGINT NOT NULL, requested_by BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Pending', reviewed_by BIGINT NULL, FOREIGN KEY(invoice_id) REFERENCES documents(id), FOREIGN KEY(requested_by) REFERENCES users(id), FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE invoice_voids (invoice_id BIGINT PRIMARY KEY, reason VARCHAR(500) NOT NULL, reviewed_by BIGINT NOT NULL, refund_due BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invoice_id) REFERENCES documents(id), FOREIGN KEY(reviewed_by) REFERENCES users(id));
